<?php use AlbaTech\Core\View; ?>
<div class="welcome-row"><div><h2>Organise your services</h2><p>Categories group related services on the public catalogue.</p></div></div><div class="category-layout"><section class="panel"><div class="panel-head"><div><h3>Existing categories</h3><p><?= count($categories) ?> categories</p></div></div><div class="category-list"><?php foreach ($categories as $category): ?><details class="category-item"><summary><span class="category-symbol"><i class="fa-solid fa-folder"></i></span><span class="category-title"><strong><?= View::escape($category['name']) ?></strong><small><?= (int)$category['service_count'] ?> services · <?= View::escape($category['slug']) ?></small></span><span class="status-pill <?= $category['status'] === 'active' ? 'status-live' : 'status-draft' ?>"><?= View::escape(ucfirst($category['status'])) ?></span><i class="fa-solid fa-chevron-down details-chevron"></i></summary><form method="post" action="/admin/categories/<?= (int)$category['id'] ?>/edit" class="category-edit"><input type="hidden" name="_csrf" value="<?= View::escape($csrf) ?>"><label class="field">Name<input name="name" required value="<?= View::escape($category['name']) ?>"></label><label class="field">Slug<input name="slug" required value="<?= View::escape($category['slug']) ?>"></label><label class="field">Description<textarea name="description" rows="3"><?= View::escape($category['description']) ?></textarea></label><div class="form-grid"><label class="field">Status<select name="status"><option value="active" <?= $category['status'] === 'active' ? 'selected' : '' ?>>Active</option><option value="inactive" <?= $category['status'] === 'inactive' ? 'selected' : '' ?>>Inactive</option></select></label><label class="field">Display order<input type="number" name="sort_order" min="0" value="<?= (int)$category['sort_order'] ?>"></label></div><button class="btn btn-primary" type="submit">Save category</button></form></details><?php endforeach; ?></div></section><section class="panel add-category-panel"><div class="panel-head"><div><h3>Add a category</h3><p>Keep names short and customer-friendly.</p></div></div><form method="post" action="/admin/categories" class="form-stack"><input type="hidden" name="_csrf" value="<?= View::escape($csrf) ?>"><label class="field">Category name<input name="name" required maxlength="160" placeholder="e.g. Web Design"></label><label class="field">URL slug<input name="slug" placeholder="web-design"><small>Leave blank to derive from the name.</small></label><label class="field">Description<textarea name="description" rows="4" placeholder="What type of services belong here?"></textarea></label><div class="form-grid"><label class="field">Status<select name="status"><option value="active">Active</option><option value="inactive">Inactive</option></select></label><label class="field">Display order<input type="number" name="sort_order" min="0" value="50"></label></div><button class="btn btn-primary" type="submit"><i class="fa-solid fa-plus"></i> Create category</button></form></section></div>
